// Normaliza a saída do agente e monta ai_meta (custo derivado, nunca digitado).
const ctx = $('Agente da fase + contexto + dossiê').item.json;
const raw = $json.output ?? $json.text ?? '';
let parsed;
try { parsed = JSON.parse(raw.replace(/^```(json)?/,'').replace(/```$/,'').trim()); } catch { parsed = { reply: String(raw) }; }
const usage = $json.tokenUsage ?? $json.usage ?? {};
const tokens_in = usage.promptTokens ?? usage.input_tokens ?? null;
const tokens_out = usage.completionTokens ?? usage.output_tokens ?? null;
const price_in = Number($env.LLM_PRICE_IN_PER_MTOK ?? 3), price_out = Number($env.LLM_PRICE_OUT_PER_MTOK ?? 15);
const cost_usd = (tokens_in != null && tokens_out != null) ? +((tokens_in * price_in + tokens_out * price_out) / 1e6).toFixed(6) : null;
return [{ json: {
  ...ctx,
  reply: parsed.reply ?? '',
  advance_to: parsed.advance_to ?? null,
  advance_reason: parsed.advance_reason ?? null,
  intervention: parsed.intervention ?? null,
  case_data: parsed.case_data ?? null,
  task: parsed.task ?? null,
  ai_meta: { agent_role: ctx.agent.role, model: ctx.agent.model, tokens_in, tokens_out, cost_usd }
}}];

